class Solution {
    public List<List<String>> findLadders(String beginWord, String endWord, List<String> wordList) {
        java.util.Set<String> dict = new java.util.HashSet<>(wordList);
        List<List<String>> result = new java.util.ArrayList<>();
        if (!dict.contains(endWord)) return result;
        java.util.Map<String, List<String>> parents = new java.util.HashMap<>();
        java.util.Set<String> current = new java.util.HashSet<>();
        current.add(beginWord);
        boolean found = false;
        while (!current.isEmpty() && !found) {
            dict.removeAll(current);
            java.util.Set<String> next = new java.util.HashSet<>();
            for (String word : current) {
                char[] arr = word.toCharArray();
                for (int i = 0; i < arr.length; i++) {
                    char orig = arr[i];
                    for (char c = 'a'; c <= 'z'; c++) {
                        arr[i] = c;
                        String nw = new String(arr);
                        if (dict.contains(nw)) {
                            next.add(nw);
                            parents.computeIfAbsent(nw, k -> new java.util.ArrayList<>()).add(word);
                            if (nw.equals(endWord)) found = true;
                        }
                    }
                    arr[i] = orig;
                }
            }
            current = next;
        }
        if (found) {
            List<String> path = new java.util.LinkedList<>();
            path.add(endWord);
            buildPaths(result, path, parents, beginWord, endWord);
        }
        return result;
    }
    private void buildPaths(List<List<String>> result, List<String> path, java.util.Map<String, List<String>> parents, String begin, String word) {
        if (word.equals(begin)) { result.add(new java.util.ArrayList<>(path)); return; }
        if (!parents.containsKey(word)) return;
        for (String p : parents.get(word)) {
            path.add(0, p);
            buildPaths(result, path, parents, begin, p);
            path.remove(0);
        }
    }
}
